// As configuracoes de resumo/preenchimento e o catalogo de etapas vem do CRM.
// Se a classificacao estiver habilitada, catalogo indisponivel bloqueia a rodada: nunca inventamos UUID.
const resposta = $('Buscar configurações globais').first().json;
const configuracao = resposta.body;
if (resposta.statusCode !== 200 || !configuracao) {
  throw new Error('EV05_CONFIG_INDISPONIVEL: verificar credencial e acesso ao CRM.');
}
for (const nome of ['resumo', 'preenchimentoAutomatico']) {
  const regra = configuracao[nome];
  if (!regra || typeof regra.habilitado !== 'boolean'
      || !Number.isInteger(regra.intervaloHoras)
      || regra.intervaloHoras < 1 || regra.intervaloHoras > 720) {
    throw new Error('EV05_CONFIG_INVALIDA: revisar contrato das configuracoes.');
  }
}

const classificarEtapa = $('Parâmetros do webhook').first().json.classificarEtapa === true;
const respostaEtapas = $('Buscar catálogo de etapas').first().json;
const etapas = Array.isArray(respostaEtapas.body) ? respostaEtapas.body : [];
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const catalogoValido = respostaEtapas.statusCode === 200
  && etapas.length > 0
  && etapas.every((etapa) => uuid.test(String(etapa.id ?? ''))
    && typeof etapa.nome === 'string' && etapa.nome.trim()
    && Number.isInteger(Number(etapa.ordem)));
if (classificarEtapa && !catalogoValido) {
  throw new Error('EV05_CATALOGO_ETAPAS_INDISPONIVEL: classificacao habilitada sem catalogo valido.');
}

const ids = new Set();
const nomes = new Set();
for (const etapa of etapas) {
  const id = String(etapa.id).toLowerCase();
  const nome = etapa.nome.trim().toLocaleLowerCase('pt-BR');
  if (ids.has(id) || nomes.has(nome)) {
    throw new Error('EV05_CATALOGO_ETAPAS_AMBIGUO: UUID ou nome duplicado.');
  }
  ids.add(id);
  nomes.add(nome);
}

return [{ json: {
  ciclo: String($execution.id),
  resumo: configuracao.resumo,
  preenchimento: configuracao.preenchimentoAutomatico,
  etapa: { habilitado: classificarEtapa },
  etapas: classificarEtapa ? etapas.map((etapa) => ({
    id: String(etapa.id), nome: etapa.nome.trim(),
    ordem: Number(etapa.ordem), resultado: etapa.resultado ?? null,
  })).sort((a, b) => a.ordem - b.ordem) : [],
  algumaRotaHabilitada: configuracao.resumo.habilitado
    || configuracao.preenchimentoAutomatico.habilitado
    || classificarEtapa,
} }];

// Os GETs de estado continuam independentes. Etapa e uma terceira tarefa, controlada no primeiro Set.
const lead = $('Identificar lead solicitado').first().json;
const configuracao = $('Validar configurações').first().json;
const respostaResumo = $('Consultar estado do resumo').first().json;
const respostaPreenchimento = $('Consultar estado do preenchimento').first().json;
const estadoResumo = respostaResumo.body;
const estadoPreenchimento = respostaPreenchimento.body;
const agora = Date.now();
const campos = ['email', 'cpf', 'empresa', 'localizacao'];

function intervaloVencido(data, horas) {
  const instante = typeof data === 'string' ? Date.parse(data) : NaN;
  return Number.isFinite(instante) && instante <= agora
    && agora - instante >= horas * 60 * 60 * 1000;
}

let gerarResumo = false;
let gerarPreenchimento = false;
let motivoResumo = 'DESABILITADO';
let motivoPreenchimento = 'DESABILITADO';
let camposVazios = [];

if (configuracao.resumo.habilitado) {
  const valido = respostaResumo.statusCode === 200
    && estadoResumo?.leadId === lead.leadId
    && typeof estadoResumo.existe === 'boolean'
    && typeof estadoResumo.contextoNovoSuficiente === 'boolean';
  if (!valido) motivoResumo = 'ESTADO_INDISPONIVEL';
  else {
    gerarResumo = !estadoResumo.existe
      || intervaloVencido(estadoResumo.atualizadoEm, configuracao.resumo.intervaloHoras);
    motivoResumo = gerarResumo ? 'ELEGIVEL' : 'AGUARDANDO_INTERVALO_OU_CONTEXTO';
  }
}

if (configuracao.preenchimento.habilitado) {
  const valido = respostaPreenchimento.statusCode === 200
    && estadoPreenchimento?.leadId === lead.leadId
    && campos.every((campo) => typeof estadoPreenchimento[campo]?.preenchido === 'boolean');
  if (!valido) motivoPreenchimento = 'ESTADO_INDISPONIVEL';
  else {
    camposVazios = campos.filter((campo) => !estadoPreenchimento[campo].preenchido);
    gerarPreenchimento = camposVazios.length > 0
      || estadoPreenchimento.ultimaAvaliacaoEm === null
      || intervaloVencido(estadoPreenchimento.ultimaAvaliacaoEm,
        configuracao.preenchimento.intervaloHoras);
    motivoPreenchimento = gerarPreenchimento ? 'ELEGIVEL' : 'AGUARDANDO_INTERVALO';
  }
}

const entrada=$('Validar entrada').first().json;
if(entrada.origem==='WEBHOOK_CRM'&&configuracao.resumo.habilitado&&motivoResumo!=='ESTADO_INDISPONIVEL') {
 gerarResumo=true; motivoResumo='SOLICITACAO_SOB_DEMANDA';
}
const classificarEtapa = configuracao.etapa.habilitado === true;
return [{ json: {
  ...lead, ciclo: configuracao.ciclo, solicitacaoId: entrada.solicitacaoId,
  gerarResumo, gerarPreenchimento, classificarEtapa, camposVazios,
  motivoResumo, motivoPreenchimento,
  motivoEtapa: classificarEtapa ? 'ELEGIVEL' : 'DESABILITADO',
  analisar: gerarResumo || gerarPreenchimento || classificarEtapa,
} }];

// Usa o contexto desta iteracao e acrescenta somente o catalogo controlado de etapas.
const regras = $('Decidir rotas do lead').first().json;
const configuracao = $('Validar configurações').first().json;
const resposta = $('Buscar histórico no PostgreSQL').first().json;
const contexto = resposta.contexto;
const etapaAtual = configuracao.etapas.find((etapa) => etapa.id === regras.etapaAtualId) ?? null;
const saida = {
  ...regras,
  catalogoEtapas: configuracao.etapas,
  etapaAtual,
  contextoValido: false,
  motivoContexto: 'CONTEXTO_INDISPONIVEL',
};
if (resposta.error || !contexto || contexto.leadId !== regras.leadId
    || contexto.atendimentoId !== regras.atendimentoId
    || contexto.situacao !== 'EM_ATENDIMENTO'
    || !Array.isArray(contexto.mensagens)
    || typeof contexto.contextoAte !== 'string'
    || !Number.isFinite(Date.parse(contexto.contextoAte))) {
  return [{ json: saida }];
}

const mensagens = contexto.mensagens.map((mensagem) => ({
  remetenteTipo: mensagem.remetenteTipo,
  tipo: mensagem.tipo,
  conteudo: typeof mensagem.conteudo === 'string' ? mensagem.conteudo : '',
  enviadoEm: mensagem.enviadoEm,
}));
if (!mensagens.some((mensagem) => mensagem.conteudo.trim())) {
  return [{ json: { ...saida, motivoContexto: 'SEM_TEXTO_PARA_ANALISAR' } }];
}

return [{ json: {
  ...saida,
  contextoValido: true,
  motivoContexto: 'OK',
  contextoAte: contexto.contextoAte,
  entradaIA: JSON.stringify({
    tarefas: {
      resumo: regras.gerarResumo,
      preenchimento: regras.gerarPreenchimento,
      etapa: regras.classificarEtapa,
    },
    camposVazios: regras.camposVazios,
    etapaAtual: etapaAtual ? {
      nome: etapaAtual.nome, ordem: etapaAtual.ordem, resultado: etapaAtual.resultado,
    } : null,
    etapasDisponiveis: configuracao.etapas.map((etapa) => ({
      nome: etapa.nome, ordem: etapa.ordem, resultado: etapa.resultado,
    })),
    mensagens,
  }),
} }];

