parameters.jsCode:
// O parser assegura a forma. Este Code valida campos e mapeia o NOME da etapa para UUID do catalogo.
const contexto = $('Preparar contexto para IA').first().json;
const bruto = $('Analisar conversa sem memória').first().json;
const analise = bruto.output ?? bruto;
const campos = ['email', 'cpf', 'empresa', 'localizacao'];
const problemas = [];
const saida = {
  leadId: contexto.leadId,
  atendimentoId: contexto.atendimentoId,
  enviarResumo: false,
  enviarPreenchimento: false,
  enviarDataNascimento: false,
  enviarEtapa: false,
  chaveResumo: contexto.solicitacaoId || ('ev05-resumo-' + contexto.leadId + '-' + contexto.ciclo),
  chavePreenchimento: 'ev05-preenchimento-' + contexto.leadId + '-' + contexto.ciclo,
  chaveDataNascimento: 'ev05-data-nascimento-' + contexto.leadId + '-' + contexto.ciclo,
  chaveEtapa: null,
  corpoResumo: null,
  corpoPreenchimento: null,
  corpoDataNascimento: null,
  corpoEtapa: null,
  etapaEscolhida: null,
  motivoResumo: contexto.motivoResumo,
  motivoPreenchimento: contexto.motivoPreenchimento,
  motivoDataNascimento: contexto.gerarPreenchimento ? 'NAO_INFORMADA' : 'DESABILITADO',
  motivoEtapa: contexto.classificarEtapa ? 'SEM_CLASSIFICACAO_SEGURA' : 'DESABILITADO',
};

if (bruto.error || !analise || typeof analise !== 'object') {
  return [{ json: {
    ...saida,
    motivoResumo: 'FALHA_IA_OU_PARSER',
    motivoPreenchimento: 'FALHA_IA_OU_PARSER',
    motivoDataNascimento: 'FALHA_IA_OU_PARSER',
    motivoEtapa: 'FALHA_IA_OU_PARSER',
    problemas: ['SAIDA_INVALIDA'],
  } }];
}

function texto(valor) {
  return typeof valor === 'string' ? valor.trim().replace(/\s+/g, ' ') : null;
}
function nomeNormalizado(valor) {
  return String(valor ?? '').trim().replace(/\s+/g, ' ').toLocaleLowerCase('pt-BR');
}
function dataNascimentoValida(valor) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(valor)) return false;
  const [ano, mes, dia] = valor.split('-').map(Number);
  const data = new Date(Date.UTC(ano, mes - 1, dia));
  return data.getUTCFullYear() === ano && data.getUTCMonth() === mes - 1
    && data.getUTCDate() === dia && data.getTime() <= Date.now();
}
function cpfValido(cpf) {
  if (!/^\d{11}$/.test(cpf) || /^(\d)\1{10}$/.test(cpf)) return false;
  for (const tamanho of [9, 10]) {
    let soma = 0;
    for (let indice = 0; indice < tamanho; indice++) soma += Number(cpf[indice]) * (tamanho + 1 - indice);
    const resto = (soma * 10) % 11;
    if (Number(cpf[tamanho]) !== (resto === 10 ? 0 : resto)) return false;
  }
  return true;
}

if (contexto.gerarResumo) {
  const resumo = typeof analise.resumo === 'string' ? analise.resumo.trim() : '';
  if (resumo) {
    saida.enviarResumo = true;
    saida.corpoResumo = { leadId: contexto.leadId, resumo, contextoGeradoEm: contexto.contextoAte };
  } else {
    saida.motivoResumo = 'RESUMO_VAZIO';
    problemas.push('RESUMO_VAZIO');
  }
}

if (contexto.gerarPreenchimento) {
  const extraido = analise.preenchimento;
  if (!extraido || typeof extraido !== 'object' || Array.isArray(extraido)) {
    saida.motivoPreenchimento = 'PREENCHIMENTO_INVALIDO';
    problemas.push('PREENCHIMENTO_INVALIDO');
  } else {
    const corpo = { leadId: contexto.leadId };
    let invalido = false;
    const nascimentoOriginal = extraido.dataNascimento;
    if (nascimentoOriginal !== null && typeof nascimentoOriginal !== 'string') {
      saida.motivoDataNascimento = 'FORMATO_INVALIDO';
      problemas.push('FORMATO_INVALIDO_DATA_NASCIMENTO');
    } else {
      const nascimento = texto(nascimentoOriginal) || null;
      if (nascimento === null) saida.motivoDataNascimento = 'NAO_INFORMADA';
      else if (!dataNascimentoValida(nascimento)) {
        saida.motivoDataNascimento = 'DATA_INVALIDA';
        problemas.push('VALOR_INVALIDO_DATA_NASCIMENTO');
      } else {
        saida.enviarDataNascimento = true;
        saida.corpoDataNascimento = { dataNascimento: nascimento };
        saida.motivoDataNascimento = 'ELEGIVEL';
      }
    }
    for (const campo of campos) {
      if (!contexto.camposVazios.includes(campo)) {
        corpo[campo] = null;
        continue;
      }
      const original = extraido[campo];
      if (original !== null && typeof original !== 'string') {
        invalido = true;
        problemas.push('FORMATO_INVALIDO_' + campo.toUpperCase());
        continue;
      }
      let valor = texto(original) || null;
      if (valor && campo === 'email') valor = valor.toLowerCase();
      if (valor && campo === 'cpf') valor = valor.replace(/\D/g, '');
      const limite = campo === 'empresa' ? 150 : 200;
      const valido = valor === null || (valor.length <= limite
        && (campo !== 'email' || /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(valor))
        && (campo !== 'cpf' || cpfValido(valor)));
      if (!valido) {
        invalido = true;
        problemas.push('VALOR_INVALIDO_' + campo.toUpperCase());
      }
      corpo[campo] = valor;
    }
    if (!invalido) {
      saida.corpoPreenchimento = corpo;
      saida.enviarPreenchimento = true;
    } else saida.motivoPreenchimento = 'CAMPOS_INVALIDOS';
  }
}

if (contexto.classificarEtapa) {
  if (analise.etapa !== null && typeof analise.etapa !== 'string') {
    saida.motivoEtapa = 'FORMATO_INVALIDO';
    problemas.push('FORMATO_INVALIDO_ETAPA');
  } else {
    const nome = texto(analise.etapa);
    if (nome) {
      const etapa = contexto.catalogoEtapas.find((item) => nomeNormalizado(item.nome) === nomeNormalizado(nome));
      if (!etapa) {
        saida.motivoEtapa = 'ETAPA_FORA_DO_CATALOGO';
        problemas.push('ETAPA_FORA_DO_CATALOGO');
      } else {
        saida.etapaEscolhida = { id: etapa.id, nome: etapa.nome, ordem: etapa.ordem, resultado: etapa.resultado };
        if (etapa.id === contexto.etapaAtualId) saida.motivoEtapa = 'JA_NA_ETAPA';
        else {
          const corte = String(contexto.contextoAte).replace(/[^0-9A-Za-z]/g, '');
          saida.enviarEtapa = true;
          saida.corpoEtapa = { etapaId: etapa.id };
          saida.chaveEtapa = 'ev05-etapa-' + contexto.leadId + '-' + etapa.id + '-' + corte;
          saida.motivoEtapa = 'ELEGIVEL';
        }
      }
    }
  }
}

return [{ json: { ...saida, problemas } }];

// Registra o resumo sem condicionar preenchimento, nascimento ou etapa.
const envio = $('Validar saída da IA').first().json;
let resumo = { status: envio.motivoResumo, httpStatus: null };
if (envio.enviarResumo) {
  const resposta = $('Salvar resumo no CRM').first().json;
  const status = resposta.statusCode ?? null;
  const sucesso = status === 200 && resposta.body?.leadId === envio.leadId
    && resposta.body?.aplicado === true;
  resumo = {
    status: sucesso ? 'SALVO' : ({
      400: 'REQUISICAO_INVALIDA', 401: 'NAO_AUTORIZADO', 403: 'SEM_PERMISSAO',
      404: 'LEAD_NAO_ELEGIVEL', 409: 'CONFLITO_IDEMPOTENCIA', 422: 'RESUMO_REJEITADO',
    }[status] ?? (status === null ? 'FALHA_REDE' : 'RESPOSTA_INESPERADA')),
    httpStatus: status,
  };
}
return [{ json: {
  leadId: envio.leadId,
  atendimentoId: envio.atendimentoId,
  resumo,
  enviarPreenchimento: envio.enviarPreenchimento,
  motivoPreenchimento: envio.motivoPreenchimento,
  enviarDataNascimento: envio.enviarDataNascimento,
  motivoDataNascimento: envio.motivoDataNascimento,
  enviarEtapa: envio.enviarEtapa,
  motivoEtapa: envio.motivoEtapa,
  etapaEscolhida: envio.etapaEscolhida,
} }];

// Saida final sanitizada: nao contem conversa, dados pessoais nem resposta bruta da IA.
const anterior = $('Registrar resultado do resumo').first().json;
const resultado = {
  leadId: anterior.leadId,
  atendimentoId: anterior.atendimentoId,
  resumo: anterior.resumo,
  preenchimento: { status: anterior.motivoPreenchimento, httpStatus: null },
  dataNascimento: { status: anterior.motivoDataNascimento, httpStatus: null },
  etapa: {
    status: anterior.motivoEtapa,
    httpStatus: null,
    nome: anterior.etapaEscolhida?.nome ?? null,
  },
  concluidoEm: new Date().toISOString(),
};

if (anterior.enviarPreenchimento) {
  const resposta = $('Salvar preenchimento no CRM').first().json;
  const status = resposta.statusCode ?? null;
  const campos = ['email', 'cpf', 'empresa', 'localizacao'];
  const permitidos = ['APLICADO', 'IGNORADO_JA_PREENCHIDO', 'IGNORADO_INVALIDO', 'AUSENTE'];
  const valido = status === 200 && resposta.body?.leadId === anterior.leadId
    && campos.every((campo) => permitidos.includes(resposta.body[campo]));
  resultado.preenchimento = {
    status: valido ? 'AVALIADO' : ({
      400: 'REQUISICAO_INVALIDA', 401: 'NAO_AUTORIZADO', 403: 'SEM_PERMISSAO',
      404: 'LEAD_NAO_ELEGIVEL', 409: 'CONFLITO_IDEMPOTENCIA',
    }[status] ?? (status === null ? 'FALHA_REDE' : 'RESPOSTA_INESPERADA')),
    httpStatus: status,
  };
  if (valido) resultado.preenchimento.campos = Object.fromEntries(
    campos.map((campo) => [campo, resposta.body[campo]]),
  );
}

if (anterior.enviarDataNascimento) {
  const resposta = $('Salvar data de nascimento no CRM').first().json;
  const status = resposta.statusCode ?? null;
  const situacao = resposta.body?.situacao;
  const valido = status === 200 && ['APLICADO', 'IGNORADO_JA_PREENCHIDO'].includes(situacao)
    && (!resposta.body?.leadId || resposta.body.leadId === anterior.leadId);
  resultado.dataNascimento = {
    status: valido ? situacao : ({
      400: 'REQUISICAO_INVALIDA', 401: 'NAO_AUTORIZADO', 403: 'SEM_PERMISSAO',
      404: 'LEAD_OU_CAMPO_NAO_ENCONTRADO', 409: 'CONFLITO_IDEMPOTENCIA', 422: 'DATA_REJEITADA',
    }[status] ?? (status === null ? 'FALHA_REDE' : 'RESPOSTA_INESPERADA')),
    httpStatus: status,
  };
}

if (anterior.enviarEtapa) {
  const resposta = $('Salvar etapa no CRM').first().json;
  const status = resposta.statusCode ?? null;
  const valido = status === 200
    && resposta.body?.leadId === anterior.leadId
    && resposta.body?.etapaId === anterior.etapaEscolhida?.id
    && typeof resposta.body?.alterado === 'boolean';
  resultado.etapa = {
    status: valido ? (resposta.body.alterado ? 'ALTERADA' : 'MANTIDA') : ({
      400: 'REQUISICAO_INVALIDA', 401: 'NAO_AUTORIZADO', 403: 'SEM_PERMISSAO',
      404: 'LEAD_NAO_ENCONTRADO', 409: 'CONFLITO_IDEMPOTENCIA', 422: 'ETAPA_REJEITADA',
    }[status] ?? (status === null ? 'FALHA_REDE' : 'RESPOSTA_INESPERADA')),
    httpStatus: status,
    nome: anterior.etapaEscolhida?.nome ?? null,
  };
}

return [{ json: resultado }];

// A IA nao foi chamada neste caminho. Nao consulta nodes de outra iteracao.
const regras = $('Decidir rotas do lead').first().json;
let motivo = 'SEM_ROTA_ELEGIVEL';
if (regras.analisar) motivo = $('Preparar contexto para IA').first().json.motivoContexto;
return [{ json: {
  leadId: regras.leadId,
  atendimentoId: regras.atendimentoId,
  resumo: { status: regras.gerarResumo ? motivo : regras.motivoResumo },
  preenchimento: { status: regras.gerarPreenchimento ? motivo : regras.motivoPreenchimento },
  etapa: { status: regras.classificarEtapa ? motivo : regras.motivoEtapa },
  concluidoEm: new Date().toISOString(),
} }];

// Header Auth continua na credencial nativa do webhook. Aqui validamos identidade.
// A solicitação do CRM é o Idempotency-Key recebido, nunca o ID da execução n8n.
function ler(nome) { try { const n=$(nome); return n.isExecuted?n.first().json:null; } catch { return null; } }
const webhook=ler('Webhook — gerar resumo manual');
const manual=ler('Parâmetros de teste manual');
const origem=webhook?'WEBHOOK_CRM':'TESTE_MANUAL_POR_TELEFONE';
const entrada=webhook??manual??{};
const corpo=entrada.body??entrada;
const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const atendimentoId=String(corpo.atendimentoId??corpo.atendimento_id??'').trim();
const leadId=String(corpo.leadId??corpo.lead_id??'').trim();
const chaves=Object.entries(entrada.headers??{}).filter(([k])=>k.toLowerCase()==='idempotency-key');
const solicitacaoId=chaves.length===1&&typeof chaves[0][1]==='string'?chaves[0][1]:'';
let telefone=String(corpo.telefone??corpo.phone??'').replace(/\D/g,'');
